# edm_finalization ----
## IO correctness ----
for (predictor_name in c("SimplexProjection", "SMapProjection", "GPEdmProjection")) {
  test_that(paste(predictor_name, "preserves finalization lifecycle behavior"), {
    #' @description EDM finalization leaves output untouched without a model, copies evaluated predictions, and refreshes output with a warning on repeated calls.
    clear()
    withr::defer(clear())
    library_embedding <- methods::new(DelayEmbedding)
    test_embedding <- methods::new(DelayEmbedding)
    series <- c(0.4, 0.9, 0.3, 0.8, 0.5, 0.7, 0.2, 0.6, 0.4, 0.9)
    library_embedding$construct(series, 2L, 1L, 1L)
    test_embedding$construct(series[5:10], 2L, 1L, 1L)
    predictor_class <- switch(predictor_name,
      SimplexProjection = SimplexProjection,
      SMapProjection = SMapProjection,
      GPEdmProjection = GPEdmProjection
    )
    predictor <- methods::new(predictor_class)
    predictor[["embedding_dimension"]] <- 2L
    predictor[["lib_de_id"]] <- library_embedding$get_id()
    predictor[["test_de_id"]] <- test_embedding$get_id()
    original <- c(101, 202, 303)
    predictor[["predictions"]]$set_values(original)
    warning_message <- paste0(
      predictor_name, " ", predictor$get_id(), " has been finalized already."
    )
    warnings_before <- get_log_warnings()
    predictor$finalize()
    expect_identical(predictor[["predictions"]]$get_values(), original)
    expect_identical(get_log_warnings(), warnings_before)
    predictor$finalize()
    expect_identical(predictor[["predictions"]]$get_values(), original)
    expect_match(get_log_warnings(), warning_message, fixed = TRUE)

    expected <- predictor$predict(
      library_embedding$get_id(), test_embedding$get_id()
    )
    expect_true(all(is.finite(expected)))
    expect_no_error(CreateTMBModel())
    objective <- TMB::MakeADFun(
      data = list(),
      parameters = list(p = get_fixed(), re = get_random()),
      DLL = "FIMS",
      silent = TRUE
    )
    objective$report()
    predictor$finalize()
    expect_equal(predictor[["predictions"]]$get_values(), expected)

    # Repeated finalization still copies the model's values; it is not a no-op.
    predictor[["predictions"]]$set_values(-123)
    warnings_before <- get_log_warnings()
    predictor$finalize()
    expect_equal(predictor[["predictions"]]$get_values(), expected)
    expect_false(identical(get_log_warnings(), warnings_before))
    expect_match(get_log_warnings(), warning_message, fixed = TRUE)
  })
}
